'use strict';

/**
 * 构建前置脚本：把 public/ 整个目录打包成 CommonJS 模块 lib/public-bundle.gen.js，
 * 供 server.js 在 SEA 运行时直接从内存提供静态资源。
 *
 * 在源码开发模式 (npm start) 下不会运行此脚本，server.js 检测到 public-bundle.gen.js
 * 不存在会自动回退到 express.static。
 */

const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const pubDir = path.join(root, 'public');
const outFile = path.join(root, 'lib', 'public-bundle.gen.js');

function walk(dir, base = '') {
  const out = {};
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const rel = path.posix.join(base, entry.name);
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      Object.assign(out, walk(full, rel));
    } else if (entry.isFile()) {
      out[rel] = fs.readFileSync(full);
    }
  }
  return out;
}

if (!fs.existsSync(pubDir)) {
  console.error(`[bundle] 找不到 public 目录: ${pubDir}`);
  process.exit(1);
}

const files = walk(pubDir);
const serialized = {};
for (const [k, v] of Object.entries(files)) {
  serialized[k] = v.toString('base64');
}

const body =
  "'use strict';\n" +
  "// AUTO-GENERATED by scripts/bundle-public.js — do not edit by hand.\n" +
  "// 在 SEA 构建时由 build-sea.js 调用生成，源码开发时不存在此文件。\n" +
  "module.exports = (() => {\n" +
  "  const encoded = " + JSON.stringify(serialized) + ";\n" +
  "  const out = {};\n" +
  "  for (const k of Object.keys(encoded)) out[k] = Buffer.from(encoded[k], 'base64');\n" +
  "  return out;\n" +
  "})();\n";

fs.writeFileSync(outFile, body, 'utf8');
const totalBytes = Object.values(files).reduce((s, b) => s + b.length, 0);
console.log(`[bundle] ${Object.keys(files).length} 个文件, ${(totalBytes / 1024).toFixed(1)} KB -> ${outFile}`);
